@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class ByteUtils_ESTest_test02 extends ByteUtils_ESTest_scaffolding {

    private static final int OUTPUT_LENGTH = 212;
    private static final int LOW_BYTE_OF_VALUE_50 = 50;

    @Test(timeout = 4000)
    public void test02() throws Throwable {
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        DataOutputStream dataOutputStream = new DataOutputStream(byteArrayOutputStream);

        ByteUtils.toLittleEndian((DataOutput) dataOutputStream, (long) (byte) 50, 212);

        assertEquals(OUTPUT_LENGTH, byteArrayOutputStream.size());
        assertEquals(expectedOutputWithFirstByteSet(), byteArrayOutputStream.toString());
    }

    private static String expectedOutputWithFirstByteSet() {
        char[] expectedOutput = new char[OUTPUT_LENGTH];
        expectedOutput[0] = LOW_BYTE_OF_VALUE_50;
        return new String(expectedOutput);
    }
}
